import{_ as e,c,o as a,ah as d,aH as t,aI as l,aJ as p}from"./chunks/framework.BoFyc1Zm.js";const g=JSON.parse('{"title":"路由组（Route groups）","description":"","frontmatter":{},"headers":[],"relativePath":"column/Nextjs/007_route_groups.md","filePath":"column/Nextjs/007_route_groups.md","lastUpdated":1767778867000}'),r={name:"column/Nextjs/007_route_groups.md"};function s(u,o,i,n,_,h){return a(),c("div",null,[...o[0]||(o[0]=[d('<h1 id="路由组-route-groups" tabindex="-1">路由组（Route groups） <a class="header-anchor" href="#路由组-route-groups" aria-label="Permalink to “路由组（Route groups）”">​</a></h1><blockquote><p>在 <code>app</code> 目录下，文件夹名称通常会被映射到 <code>URL</code> 中，但你可以将文件夹标记为<code>路由组</code>，阻止文件夹名称被映射到 <code>URL</code> 中。</p></blockquote><p>使用路由组，你可以将路由和项目文件按照逻辑进行分组，但不会影响 <code>URL</code> 路径结构。路由组可用于比如：</p><ul><li>按站点、意图、团队等将路由分组</li><li>在同一层级中创建多个布局，甚至是创建多个根布局 那么该如何标记呢？把文件夹用括号括住就可以了，就比如 <code>(dashboard)</code>。</li></ul><h2 id="按逻辑分组" tabindex="-1">按逻辑分组 <a class="header-anchor" href="#按逻辑分组" aria-label="Permalink to “按逻辑分组”">​</a></h2><blockquote><p>将路由按逻辑分组，但不影响 <code>URL</code> 路径：</p></blockquote><p><img src="'+t+'" alt="alt text"></p><p>你会发现，最终的 <code>URL</code> 中省略了带括号的文件夹（上图中的<code>(marketing)</code>和<code>(shop)</code>）。</p><h2 id="创建不同布局" tabindex="-1">创建不同布局 <a class="header-anchor" href="#创建不同布局" aria-label="Permalink to “创建不同布局”">​</a></h2><blockquote><p>借助路由组，即便在同一层级，也可以创建不同的布局：</p></blockquote><p><img src="'+l+'" alt="alt text"></p><p>在这个例子中，<code>/account</code> 、<code>/cart</code>、<code>/checkout</code> 都在同一层级。</p><ul><li>但是 <code>/account</code>和 <code>/cart</code>使用的是 <code>/app/(shop)/layout.js</code>布局和<code>app/layout.js</code>布局</li><li><code>/checkout</code>使用的是 <code>app/layout.js</code></li></ul><h2 id="创建多个根布局" tabindex="-1">创建多个根布局 <a class="header-anchor" href="#创建多个根布局" aria-label="Permalink to “创建多个根布局”">​</a></h2><blockquote><p>创建多个根布局：</p></blockquote><p><img src="'+p+'" alt="alt text"></p><p>创建多个根布局，你需要删除掉 <code>app/layout.js</code> 文件，然后在每组都创建一个 <code>layout.js</code>文件。创建的时候要注意，因为是根布局，所以要有 <code>&lt;html&gt;</code> 和 <code>&lt;body&gt;</code> 标签。</p><p>这个功能很实用，比如你将<code>前台购买页面</code>和<code>后台管理页面</code>都放在一个项目里，一个 <code>C 端</code>，一个 <code>B 端</code>，两个项目的布局肯定不一样，借助路由组，就可以轻松实现区分。</p><p>再多说几点：</p><ul><li>路由组的命名除了用于组织之外并无特殊意义。它们不会影响 <code>URL</code> 路径。</li><li>注意不要解析为相同的 <code>URL</code> 路径。举个例子，因为路由组不影响 <code>URL</code> 路径，所以 <code>(marketing)/about/page.js</code>和 <code>(shop)/about/page.js</code>都会解析为 <code>/about</code>，这会导致报错。</li><li>创建多个根布局的时候，因为删除了顶层的 <code>app/layout.js</code>文件，访问 <code>/</code>会报错，所以<code>app/page.js</code>需要定义在其中一个路由组中。</li><li>跨根布局导航会导致页面完全重新加载，就比如使用 <code>app/(shop)/layout.js</code>根布局的 <code>/cart</code> 跳转到使用 <code>app/(marketing)/layout.js</code>根布局的 <code>/blog</code> 会导致页面重新加载（<code>full page load</code>）。</li></ul>',20)])])}const b=e(r,[["render",s]]);export{g as __pageData,b as default};
